MR = M[:NR]; li = LL[:, NR:]; ei = logsumexp(li,1); iin = np.exp(li-ei[:,None])@M[NR:]
def rule_ll(e, target_side=True):
    Mp = (1-e)*MR + e*(1-MR); S = Mp.sum(1)
    out = np.zeros((len(uniq), NR))
    for j,s in enumerate(uniq):
        shown = np.zeros(NR)
        for x in s:
            m = Mp[:, x-1]; out[j] += np.log(0.9*m/np.maximum(S-shown,1)+0.01); shown += m
    return out, (Mp if target_side else MR)
def nll3(p, ts=True):
    l0, lapse, g = expit(p[:3]); e = expit(p[3])
    lr, Mt = rule_ll(e, ts); er = logsumexp(lr,1); rin = np.exp(lr-er[:,None])@Mt
    pr = expit(np.log(l0)-np.log(NR)+er - np.log1p(-l0)+np.log(NI)-ei)[:,None]
    q = np.clip((1-lapse)*(pr*rin+(1-pr)*iin)[si,tg-1]+lapse*g,1e-6,1-1e-6)
    return -np.sum(y*np.log(q)+(1-y)*np.log(1-q))
for ts in [True, False]:
  for e0 in [-6,-4,-3]:
    r = minimize(lambda p: nll3(p,ts), [-0.68,-5,5,e0], method="Nelder-Mead", options=dict(maxiter=2000))
    print(ts, e0, r.fun, expit(r.x))
